def concesso(key, op):
    v = vis.get(key, 'admin' if key == 'piano' else 'tutti')
    if v in ('nascosto', 'admin'): return False
    if isinstance(v, dict) and v.get('tipo') == 'selezionati': return op in (v.get('operatori') or [])
    return True
