h.append('''<script>
const CH='diario_scheda_permessi';
function init(){document.querySelectorAll('select.c').forEach(s=>{if(s.value===''&&s.dataset.orig!=null)s.value=s.dataset.orig})}
function stato(){const s={meta:{},sel:{},note:{}};document.querySelectorAll('[data-meta]').forEach(i=>s.meta[i.dataset.meta]=i.value);document.querySelectorAll('select.c').forEach(x=>{if(x.value!==x.dataset.orig)s.sel[x.dataset.sel]=x.value});document.querySelectorAll('textarea[data-nota]').forEach(t=>{if(t.value.trim())s.note[t.dataset.nota]=t.value});firmeStato(s);return s}
// FIRME: per ogni blocco uno o piu firmatari (ruolo, nome, data, firma
// disegnata con mouse o dito). Le firme finiscono nelle risposte e nella
// copia compilata; in stampa restano ruolo, nome, data e la firma o la riga.
const RUOLI_FIRMA=["HR", "Direzione", "Responsabile FoBoSlot", "Sostituto FoBoSlot", "Supervisor", "Compliance", "Altro"];
function firmaBox(bl,i,dati){dati=dati||{};const id=bl+'-'+i;const opts=RUOLI_FIRMA.map(r=>'<option'+(dati.ruolo===r?' selected':'')+'>'+r+'</option>').join('');return '<div class="firma" data-fid="'+id+'"><div><label>Chi firma</label><select data-fr="'+id+'"><option value="">scegli</option>'+opts+'</select></div><div><label>Nome e cognome</label><input data-fn="'+id+'" value="'+(dati.nome||'').replace(/"/g,'&quot;')+'"></div><div><label>Data</label><input data-fd="'+id+'" value="'+(dati.data||'')+'" placeholder="gg.mm.aaaa"></div><div class="pad"><canvas data-firma="'+id+'"></canvas><button type="button" class="no-stampa" onclick="firmaPulisci(\''+id+'\')">Cancella firma</button><button type="button" class="no-stampa" style="right:96px" onclick="firmaRimuovi(\''+id+'\')">Togli</button><small>Firma con il mouse o con il dito; su carta, firma sulla riga.</small></div></div>'}
function firmaAggiungi(bl,dati){const c=document.querySelector('.firme[data-blocco="'+bl+'"] .firme-lista');if(!c)return null;const i=c.children.length;c.insertAdjacentHTML('beforeend',firmaBox(bl,i,dati));const box=c.lastElementChild;firmaInitCanvas(box.querySelector('canvas'));return box}
function firmaRimuovi(id){const box=document.querySelector('.firma[data-fid="'+id+'"]');if(!box)return;const lista=box.parentNode;if(lista.children.length<=1){firmaPulisci(id);box.querySelector('select').value='';box.querySelectorAll('input').forEach(i=>i.value='');salvaLocale();return}box.remove();salvaLocale()}
function firmaInitCanvas(cv){cv.width=880;cv.height=240;const ctx=cv.getContext('2d');ctx.lineWidth=3;ctx.lineCap='round';ctx.strokeStyle='#1c1a17';let giu=false,ux=0,uy=0;const pos=e=>{const r=cv.getBoundingClientRect();return[(e.clientX-r.left)*cv.width/r.width,(e.clientY-r.top)*cv.height/r.height]};cv.addEventListener('pointerdown',e=>{giu=true;[ux,uy]=pos(e);cv.setPointerCapture(e.pointerId);const d=cv.closest('.firma').querySelector('input[data-fd]');if(d&&!d.value)d.value=new Date().toLocaleDateString('it-IT')});cv.addEventListener('pointermove',e=>{if(!giu)return;const[x,y]=pos(e);ctx.beginPath();ctx.moveTo(ux,uy);ctx.lineTo(x,y);ctx.stroke();ux=x;uy=y;cv.dataset.firmata='1'});const fine=()=>{if(giu){giu=false;salvaLocale()}};cv.addEventListener('pointerup',fine);cv.addEventListener('pointerleave',fine)}
function firmaInit(){document.querySelectorAll('.firme').forEach(b=>{if(!b.querySelector('.firma'))firmaAggiungi(b.dataset.blocco)})}
function firmaPulisci(id){const cv=document.querySelector('canvas[data-firma="'+id+'"]');if(!cv)return;cv.getContext('2d').clearRect(0,0,cv.width,cv.height);delete cv.dataset.firmata;salvaLocale()}
function firmeStato(s){s.firme={};document.querySelectorAll('.firme').forEach(b=>{s.firme[b.dataset.blocco]=[...b.querySelectorAll('.firma')].map(box=>{const cv=box.querySelector('canvas');return{ruolo:box.querySelector('select').value,nome:box.querySelector('input[data-fn]').value,data:box.querySelector('input[data-fd]').value,img:cv.dataset.firmata?cv.toDataURL('image/png'):''}}).filter(f=>f.ruolo||f.nome||f.data||f.img)})}
function firmeApplica(s){Object.keys((s&&s.firme)||{}).forEach(bl=>{const lista=(s.firme[bl]||[]);if(!lista.length)return;const c=document.querySelector('.firme[data-blocco="'+bl+'"] .firme-lista');if(!c)return;c.innerHTML='';lista.forEach(f=>{const box=firmaAggiungi(bl,f);if(box&&f.img){const cv=box.querySelector('canvas');const im=new Image();im.onload=()=>{cv.getContext('2d').drawImage(im,0,0,cv.width,cv.height);cv.dataset.firmata='1'};im.src=f.img}})})}

function applica(s){if(!s)return;Object.keys(s.meta||{}).forEach(k=>{const i=document.querySelector('[data-meta="'+k+'"]');if(i)i.value=s.meta[k]});Object.keys(s.sel||{}).forEach(k=>{const x=document.querySelector('select[data-sel="'+k+'"]');if(x)x.value=s.sel[k]});Object.keys(s.note||{}).forEach(k=>{const t=document.querySelector('textarea[data-nota="'+k+'"]');if(t)t.value=s.note[k]});firmeApplica(s)}
function colora(){let n=0;document.querySelectorAll('select.c').forEach(x=>{x.classList.toggle('si',x.value==='si');const m=x.value!==x.dataset.orig;x.classList.toggle('mod',m);if(m)n++});document.querySelectorAll('tr[data-r]').forEach(tr=>tr.classList.toggle('ha-mod',!!tr.querySelector('select.c.mod')||[...tr.querySelectorAll('textarea')].some(t=>t.value.trim())));document.getElementById('prog').textContent=n?'Modifiche: '+n:'Nessuna modifica'}
function salvaLocale(){try{localStorage.setItem(CH,JSON.stringify(stato()))}catch(e){}}
document.addEventListener('change',()=>{colora();salvaLocale()});document.addEventListener('input',salvaLocale);
function soloMod(){document.body.classList.toggle('solo-mod');document.getElementById('btn-mod').textContent=document.body.classList.contains('solo-mod')?'Mostra tutto':'Mostra solo le modifiche'}
function salvaCopia(){const s=stato();s.salvatoIl=new Date().toISOString();const tagS='<'+'script id="risposte-incorporate">';const tagE='<'+'/script>';let html=document.documentElement.outerHTML;const i1=html.indexOf(tagS);if(i1>=0){const i2=html.indexOf(tagE,i1);html=html.slice(0,i1)+html.slice(i2+tagE.length)}const json=JSON.stringify(s).split('</').join('<'+String.fromCharCode(92)+'/');html='<!DOCTYPE html>'+String.fromCharCode(10)+html.replace('</body>',tagS+'window.__RISPOSTE='+json+';'+tagE+'</body>');const b=new Blob([html],{type:'text/html'});const a=document.createElement('a');a.href=URL.createObjectURL(b);a.download='scheda_permessi_controllata_'+(s.meta.nome||'compilata').replace(/[^a-z0-9]+/gi,'_')+'.html';a.click()}
function azzera(){if(!confirm('Togliere tutte le modifiche e tornare allo stato attuale?'))return;localStorage.removeItem(CH);document.querySelectorAll('select.c').forEach(x=>x.value=x.dataset.orig);document.querySelectorAll('textarea').forEach(t=>t.value='');colora()}
init();firmaInit();if(window.__RISPOSTE){applica(window.__RISPOSTE)}else{try{applica(JSON.parse(localStorage.getItem(CH)||'null'))}catch(e){}}colora();
</script></body></html>''')
open('SCHEDA_PERMESSI_ATTUALI.html', 'w').write('\n'.join(h)); print('scheda ok', len(ops), 'operatori')
